static inline void RENAME(planar2x)(const uint8_t *src, uint8_t *dst, long srcWidth, long srcHeight, long srcStride, long dstStride)

{

	long x,y;



	dst[0]= src[0];



	// first line

	for(x=0; x<srcWidth-1; x++){

		dst[2*x+1]= (3*src[x] +   src[x+1])>>2;

		dst[2*x+2]= (  src[x] + 3*src[x+1])>>2;

	}

	dst[2*srcWidth-1]= src[srcWidth-1];



        dst+= dstStride;



	for(y=1; y<srcHeight; y++){

#if defined (HAVE_MMX2) || defined (HAVE_3DNOW)

		const long mmxSize= srcWidth&~15;

		asm volatile(

			"mov %4, %%"REG_a"		\n\t"

			"1:				\n\t"

			"movq (%0, %%"REG_a"), %%mm0	\n\t"

			"movq (%1, %%"REG_a"), %%mm1	\n\t"

			"movq 1(%0, %%"REG_a"), %%mm2	\n\t"

			"movq 1(%1, %%"REG_a"), %%mm3	\n\t"

			"movq -1(%0, %%"REG_a"), %%mm4	\n\t"

			"movq -1(%1, %%"REG_a"), %%mm5	\n\t"

			PAVGB" %%mm0, %%mm5		\n\t"

			PAVGB" %%mm0, %%mm3		\n\t"

			PAVGB" %%mm0, %%mm5		\n\t"

			PAVGB" %%mm0, %%mm3		\n\t"

			PAVGB" %%mm1, %%mm4		\n\t"

			PAVGB" %%mm1, %%mm2		\n\t"

			PAVGB" %%mm1, %%mm4		\n\t"

			PAVGB" %%mm1, %%mm2		\n\t"

			"movq %%mm5, %%mm7		\n\t"

			"movq %%mm4, %%mm6		\n\t"

			"punpcklbw %%mm3, %%mm5		\n\t"

			"punpckhbw %%mm3, %%mm7		\n\t"

			"punpcklbw %%mm2, %%mm4		\n\t"

			"punpckhbw %%mm2, %%mm6		\n\t"

#if 1

			MOVNTQ" %%mm5, (%2, %%"REG_a", 2)\n\t"

			MOVNTQ" %%mm7, 8(%2, %%"REG_a", 2)\n\t"

			MOVNTQ" %%mm4, (%3, %%"REG_a", 2)\n\t"

			MOVNTQ" %%mm6, 8(%3, %%"REG_a", 2)\n\t"

#else

			"movq %%mm5, (%2, %%"REG_a", 2)	\n\t"

			"movq %%mm7, 8(%2, %%"REG_a", 2)\n\t"

			"movq %%mm4, (%3, %%"REG_a", 2)	\n\t"

			"movq %%mm6, 8(%3, %%"REG_a", 2)\n\t"

#endif

			"add $8, %%"REG_a"		\n\t"

			" js 1b				\n\t"

			:: "r" (src + mmxSize  ), "r" (src + srcStride + mmxSize  ),

			   "r" (dst + mmxSize*2), "r" (dst + dstStride + mmxSize*2),

			   "g" (-mmxSize)

			: "%"REG_a



		);

#else

		const long mmxSize=1;

#endif

		dst[0        ]= (3*src[0] +   src[srcStride])>>2;

		dst[dstStride]= (  src[0] + 3*src[srcStride])>>2;



		for(x=mmxSize-1; x<srcWidth-1; x++){

			dst[2*x          +1]= (3*src[x+0] +   src[x+srcStride+1])>>2;

			dst[2*x+dstStride+2]= (  src[x+0] + 3*src[x+srcStride+1])>>2;

			dst[2*x+dstStride+1]= (  src[x+1] + 3*src[x+srcStride  ])>>2;

			dst[2*x          +2]= (3*src[x+1] +   src[x+srcStride  ])>>2;

		}

		dst[srcWidth*2 -1            ]= (3*src[srcWidth-1] +   src[srcWidth-1 + srcStride])>>2;

		dst[srcWidth*2 -1 + dstStride]= (  src[srcWidth-1] + 3*src[srcWidth-1 + srcStride])>>2;



		dst+=dstStride*2;

		src+=srcStride;

	}



	// last line

#if 1

	dst[0]= src[0];



	for(x=0; x<srcWidth-1; x++){

		dst[2*x+1]= (3*src[x] +   src[x+1])>>2;

		dst[2*x+2]= (  src[x] + 3*src[x+1])>>2;

	}

	dst[2*srcWidth-1]= src[srcWidth-1];

#else

	for(x=0; x<srcWidth; x++){

		dst[2*x+0]=

		dst[2*x+1]= src[x];

	}

#endif



#ifdef HAVE_MMX

asm volatile(   EMMS" \n\t"

        	SFENCE" \n\t"

        	:::"memory");

#endif

}

static void gen_mtmsr(DisasContext *ctx)

{

#if defined(CONFIG_USER_ONLY)

    gen_inval_exception(ctx, POWERPC_EXCP_PRIV_REG);

#else

    if (unlikely(ctx->pr)) {

        gen_inval_exception(ctx, POWERPC_EXCP_PRIV_REG);

        return;

    }

    if (ctx->opcode & 0x00010000) {

        /* Special form that does not need any synchronisation */

        TCGv t0 = tcg_temp_new();

        tcg_gen_andi_tl(t0, cpu_gpr[rS(ctx->opcode)], (1 << MSR_RI) | (1 << MSR_EE));

        tcg_gen_andi_tl(cpu_msr, cpu_msr, ~(target_ulong)((1 << MSR_RI) | (1 << MSR_EE)));

        tcg_gen_or_tl(cpu_msr, cpu_msr, t0);

        tcg_temp_free(t0);

    } else {

        TCGv msr = tcg_temp_new();



        /* XXX: we need to update nip before the store

         *      if we enter power saving mode, we will exit the loop

         *      directly from ppc_store_msr

         */

        gen_update_nip(ctx, ctx->nip);

#if defined(TARGET_PPC64)

        tcg_gen_deposit_tl(msr, cpu_msr, cpu_gpr[rS(ctx->opcode)], 0, 32);

#else

        tcg_gen_mov_tl(msr, cpu_gpr[rS(ctx->opcode)]);

#endif

        gen_helper_store_msr(cpu_env, msr);

        tcg_temp_free(msr);

        /* Must stop the translation as machine state (may have) changed */

        /* Note that mtmsr is not always defined as context-synchronizing */

        gen_stop_exception(ctx);

    }

#endif

}

static int huff_build10(VLC *vlc, uint8_t *len)

{

    HuffEntry he[1024];

    uint32_t codes[1024];

    uint8_t bits[1024];

    uint16_t syms[1024];

    uint32_t code;

    int i;



    for (i = 0; i < 1024; i++) {

        he[i].sym = 1023 - i;

        he[i].len = len[i];



    }

    AV_QSORT(he, 1024, HuffEntry, huff_cmp_len10);



    code = 1;

    for (i = 1023; i >= 0; i--) {

        codes[i] = code >> (32 - he[i].len);

        bits[i]  = he[i].len;

        syms[i]  = he[i].sym;

        code += 0x80000000u >> (he[i].len - 1);

    }



    ff_free_vlc(vlc);

    return ff_init_vlc_sparse(vlc, FFMIN(he[1023].len, 12), 1024,

                              bits,  sizeof(*bits),  sizeof(*bits),

                              codes, sizeof(*codes), sizeof(*codes),

                              syms,  sizeof(*syms),  sizeof(*syms), 0);

}

